import{_ as r,o,c as d,ag as n}from"./chunks/framework.KxDd3USm.js";const l=JSON.parse('{"title":"06.6 应用层协议与端口 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/06-应用层协议.md","filePath":"06-计算机网络/06-应用层协议.md"}'),s={name:"06-计算机网络/06-应用层协议.md"};function g(P,t,a,e,T,u){return o(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="_06-6-应用层协议与端口-★★★" tabindex="-1">06.6 应用层协议与端口 ★★★ <a class="header-anchor" href="#_06-6-应用层协议与端口-★★★" aria-label="Permalink to &quot;06.6 应用层协议与端口 ★★★&quot;">​</a></h1><h3 id="端口是什么、怎么记" tabindex="-1">端口是什么、怎么记 <a class="header-anchor" href="#端口是什么、怎么记" aria-label="Permalink to &quot;端口是什么、怎么记&quot;">​</a></h3><p>一台主机上同时跑着浏览器、微信、下载器……数据到了该交给谁？传输层用 <strong>16 位端口号</strong>区分进程。范围 0～65535；<strong>知名端口 1～1023</strong> 固定分配给常见服务。端口成对工作：服务器端用知名端口&quot;听&quot;，客户端随机开口。<strong>IP 地址找到主机，端口找到主机里的程序</strong>。</p><h3 id="常用协议端口表-必背-年年考" tabindex="-1">常用协议端口表（必背，年年考） <a class="header-anchor" href="#常用协议端口表-必背-年年考" aria-label="Permalink to &quot;常用协议端口表（必背，年年考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>端口</th><th>传输层</th><th>功能一句话</th></tr></thead><tbody><tr><td><strong>FTP</strong></td><td><strong>20（数据）/ 21（控制）</strong></td><td>TCP</td><td>文件传输</td></tr><tr><td>SSH</td><td>22</td><td>TCP</td><td>安全远程登录</td></tr><tr><td><strong>TELNET</strong></td><td><strong>23</strong></td><td>TCP</td><td>远程登录（明文，不安全）</td></tr><tr><td><strong>SMTP</strong></td><td><strong>25</strong></td><td>TCP</td><td><strong>发</strong>邮件（推）</td></tr><tr><td><strong>DNS</strong></td><td><strong>53</strong></td><td><strong>UDP 为主</strong>（区域传送用 TCP）</td><td>域名 ↔ IP 解析</td></tr><tr><td>TFTP</td><td>69</td><td>UDP</td><td>简单文件传输</td></tr><tr><td><strong>HTTP</strong></td><td><strong>80</strong></td><td>TCP</td><td>网页传输</td></tr><tr><td>POP3</td><td><strong>110</strong></td><td>TCP</td><td><strong>收</strong>邮件（拉）</td></tr><tr><td>SNMP</td><td>161</td><td>UDP</td><td>网络设备管理</td></tr><tr><td><strong>HTTPS</strong></td><td><strong>443</strong></td><td>TCP</td><td>加密的网页传输</td></tr><tr><td><strong>DHCP</strong></td><td><strong>67 / 68</strong></td><td><strong>UDP</strong></td><td><strong>自动分配 IP 配置</strong></td></tr></tbody></table><p><strong>记忆口诀</strong>：&quot;<strong>21 号 FTP 控制，20 传数据；23 远登、25 发信、53 域名、80 网页、110 收信、443 加密</strong>&quot;。UDP 一族只有四个：<strong>DNS、TFTP、SNMP、DHCP</strong>（口诀：&quot;域名、简单传文件、网管、拿地址，都图个快&quot;），其余常考应用协议全走 TCP。</p><p><strong>DHCP 单独强调</strong>（常考功能题）：DHCP 的作用是让主机开机后<strong>自动获取 IP 地址、子网掩码、默认网关、DNS 服务器</strong>等配置，免手工设置；采用 UDP，客户端从 68 端口向服务器 67 端口申请。工作过程&quot;发现（Discover）→ 提供（Offer）→ 请求（Request）→ 确认（Ack）&quot;四步，知道名字即可。</p><p><strong>反例演示</strong>：</p><ol><li>&quot;SMTP 端口 110&quot;——<strong>错</strong>。<strong>SMTP 发信用 25，POP3 收信用 110</strong>，这组是端口题最经典的调包陷阱。</li><li>&quot;DNS 用 TCP 53&quot;——<strong>错一半</strong>。DNS 日常查询用 <strong>UDP 53</strong>，只有区域传送（主从服务器同步整个区域文件）才用 TCP。选择题若笼统问 DNS 的端口号，答 53；若问传输层载体，答&quot;主要 UDP&quot;。</li><li>&quot;FTP 端口是 20&quot;——<strong>不完整</strong>。FTP 是<strong>双端口</strong>：21 控制、20 传数据；题目问&quot;控制连接&quot;答 21。</li></ol><p><strong>应试动作</strong>：① 端口表按口诀背到看到协议名 1 秒报端口（反向也要会：给端口报协议）；② 牢记 UDP 四兄弟 DNS/TFTP/SNMP/DHCP，其余默认 TCP；③ SMTP/POP3 是&quot;发/收&quot;配对，FTP 是&quot;21 控制/20 数据&quot;配对，专防调包。</p>',10)])])}const _=r(s,[["render",g]]);export{l as __pageData,_ as default};
